<script setup lang="ts">
import { ref,onMounted,computed } from 'vue'
import { NButton,NInput } from 'naive-ui'
import { api,post,str,pretty,rows,type Row } from '../api'
import Notice from '../components/Notice.vue'
import AppIcon from '../components/AppIcon.vue'
import ConfirmDialog from '../components/ConfirmDialog.vue'
import { t, formatDateTime, formatNumber, displayState } from '../i18n'
const auditPage=ref(0),auditHasNext=ref(false),auditBusy=ref(false),auditError=ref<unknown>(''),pageSize=50,actionBusy=ref(false),settings=ref<Row>({}),capabilities=ref<Row>({}),audits=ref<Row[]>([]),error=ref<unknown>(''),busy=ref(false),mirror=ref(''),testImage=ref(''),diagnostics=ref<Row|null>(null),daemon=ref<Row|null>(null),preview=ref<Row|null>(null),confirm=ref(false)
const canModify=computed(()=>Boolean((capabilities.value['host.daemon_config'] as Row|undefined)?.available&&(capabilities.value['host.service_restart'] as Row|undefined)?.available))
async function load(){busy.value=true;try{settings.value=await api('/settings');const c=await api('/hosts/local/capabilities');capabilities.value=(c.capabilities??{}) as Row;await loadAudit();error.value=''}catch(e){error.value=e}finally{busy.value=false}}
async function loadAudit(){auditBusy.value=true;auditError.value='';try{const pageRows=rows(await api(`/audit?limit=${pageSize+1}&offset=${auditPage.value*pageSize}`));auditHasNext.value=pageRows.length>pageSize;audits.value=pageRows.slice(0,pageSize)}catch(e){auditError.value=e}finally{auditBusy.value=false}}
async function diagnose(){busy.value=true;try{diagnostics.value=await post('/host/diagnostics',{url:mirror.value.split('\n')[0],image:testImage.value,confirm_pull:Boolean(testImage.value)})}catch(e){error.value=e}finally{busy.value=false}}
async function readDaemon(){try{daemon.value=await api('/host/daemon')}catch(e){error.value=e}}
async function previewDaemon(){try{preview.value=await post('/host/daemon/preview',{mirrors:mirror.value.split('\n').map(s=>s.trim()).filter(Boolean)})}catch(e){error.value=e}}
async function apply(){if(actionBusy.value)return;actionBusy.value=true;try{await post('/host/daemon/apply',{mirrors:mirror.value.split('\n').map(s=>s.trim()).filter(Boolean),revision:preview.value?.revision,confirm:true,confirm_restart:true});confirm.value=false;await load()}catch(e){error.value=e}finally{actionBusy.value=false}}
onMounted(load)
</script>
<template><div class="toolbar"><p class="muted">{{ t('settings.capabilityInfo') }}</p><n-button @click="load" :loading="busy"><AppIcon name="refresh"/>{{ t('settings.refresh') }}</n-button></div><Notice :error="error"/><div class="dashboard-grid"><section class="panel"><div class="panel-title"><h3>{{ t('settings.platform') }}</h3><span class="eyebrow">{{ t('settings.application') }}</span></div><dl class="facts"><div v-for="key in ['version','mode','listen','data_dir']" :key="key"><dt>{{ {version:t('settings.version'),mode:t('settings.mode'),listen:t('settings.listen'),data_dir:t('settings.data_dir')}[key] }}</dt><dd>{{ str(settings[key]) }}</dd></div></dl><h4>{{ t('settings.paths') }}</h4><pre class="json-block">{{ pretty({allowed_paths:settings.allowed_paths,path_mappings:settings.path_mappings}) }}</pre></section><section class="panel"><div class="panel-title"><h3>{{ t('settings.hostCapabilities') }}</h3><span class="eyebrow">{{ t('settings.capabilities') }}</span></div><div v-for="(value,key) in capabilities" :key="key" class="capability"><div><strong>{{ key }}</strong><small>{{ str((value as Row).reason) }}</small></div><span class="tag" :class="(value as Row).available?'success':'warning'">{{ (value as Row).available?t('settings.available'):t('settings.restricted') }}</span></div></section></div><section class="panel section-gap"><div class="panel-title"><h3>{{ t('settings.diagnostics') }}</h3><span class="eyebrow">{{ t('settings.diagnosticsCaption') }}</span></div><p class="muted">{{ t('settings.diagnosticsInfo') }}</p><div class="form-field"><label for="diagnostic-mirror">{{ t('settings.mirrorLabel') }}</label><n-input :input-props="{id:'diagnostic-mirror'}" v-model:value="mirror" type="textarea" :autosize="{minRows:2}" placeholder="https://registry.example.com" @update:value="preview=null"/></div><div class="form-field"><label for="diagnostic-image">{{ t('settings.imageLabel') }}</label><n-input :input-props="{id:'diagnostic-image'}" v-model:value="testImage" placeholder="hello-world:latest"/></div><div class="actions"><n-button :loading="busy" :disabled="!mirror" @click="diagnose">{{ t('settings.diagnose') }}</n-button><n-button @click="readDaemon">{{ t('settings.readConfig') }}</n-button><n-button :disabled="!canModify" @click="previewDaemon">{{ t('settings.previewConfig') }}</n-button><n-button type="warning" :disabled="!canModify||!preview" @click="error='';confirm=true">{{ t('settings.apply') }}</n-button></div><p v-if="!canModify" class="notice warning">{{ t('settings.manualWarning') }}</p><pre v-if="diagnostics" class="json-block">{{ pretty(diagnostics) }}</pre><pre v-if="daemon" class="json-block">{{ pretty(daemon) }}</pre><pre v-if="preview" class="json-block">{{ pretty(preview) }}</pre></section><section class="panel table-panel section-gap"><div class="panel-title"><h3>{{ t('settings.audit') }}</h3><span class="eyebrow">{{ t('settings.auditCaption') }}</span></div><div class="table-scroll"><table><thead><tr><th>{{ t('settings.actor') }}</th><th>{{ t('settings.actionTarget') }}</th><th>{{ t('settings.result') }}</th><th>{{ t('settings.time') }}</th></tr></thead><tbody><tr v-for="(audit,i) in audits" :key="i"><td>{{ str(audit.actor_id) }}</td><td>{{ str(audit.action) }}<code>{{ [audit.resource_type,audit.resource_id].filter(Boolean).join(' / ')||'—' }}</code></td><td>{{ displayState(audit.result) }}</td><td>{{ formatDateTime(audit.created_at) }}</td></tr></tbody></table></div><Notice :error="auditError" :busy="auditBusy" :empty="!auditBusy&&!auditError&&!audits.length"/><div class="pagination"><span>{{ t('settings.pagination', { page: formatNumber(auditPage+1), count: formatNumber(audits.length) }) }}</span><div class="actions"><n-button size="small" :disabled="auditBusy||auditPage===0" @click="auditPage--;loadAudit()">{{ t('settings.previous') }}</n-button><n-button size="small" :disabled="auditBusy||!auditHasNext" @click="auditPage++;loadAudit()">{{ t('settings.next') }}</n-button></div></div></section><ConfirmDialog v-model:show="confirm" :title="t('settings.confirmTitle')" :error="error" :busy="actionBusy" :detail="t('settings.restartWarning')" @confirm="apply"/></template>
